html:
{{ print_control(doc) }}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set employee = frappe.get_doc("Employee", doc.employee) -%}
{%- set signer = frappe.db.get_single_value("Onboarding Settings", "executive_director") -%}
<style>
.lpl-letter { font-family: Cambria, Georgia, serif; font-size: 12.5px; color: #000; line-height: 1.55; }
.lpl-letter p { margin: 0 0 12px; }
.lpl-letter .addr { font-weight: bold; margin: 0; }
.lpl-letter h4 { font-size: 12.5px; font-weight: bold; text-decoration: underline; margin: 14px 0 6px; }
.lpl-letter .logo { text-align: right; margin: 0 0 18px; }
.lpl-letter .sign-off { margin: 30px 0 0; }
.lpl-letter .who { font-weight: bold; margin: 0; }
.lpl-letter .ack { margin-top: 22px; }
.lpl-letter ol { margin: 0 0 12px; }
</style>
<div class="lpl-letter">
{%- if doc.custom_reason != "Medical Grounds" %}
<p><em>The Termination on Medical Grounds letter is for a separation on medical grounds; this one is {{ v(doc.custom_reason or "without a reason") }}.</em></p>
{%- else %}
{% if logo %}<p class="logo"><img src="{{ logo }}" style="max-height:64px"></p>{% endif %}
<p class="addr">{{ day(doc.custom_termination_date or doc.creation) }}</p>
<p>&nbsp;</p>
<p class="addr">{{ v(employee.salutation) }} {{ v(employee.employee_name) }}</p>
<p class="addr">{{ v(employee.employee_number or employee.name) }}</p>
<p class="addr">Division &ndash; {{ v(employee.department) }}</p>
<p class="addr">Plant, {{ v(employee.branch) }}</p>
<p>&nbsp;</p>
<p><b>Dear {{ v(employee.first_name or employee.employee_name) }},</b></p>
<h4>RE: TERMINATION ON MEDICAL GROUNDS</h4>
<p>Following your inability to execute your work to do due to your health challenges, the company has taken a decision to retire you on medical grounds.</p>
<p>This is to inform you that your last day of work was <b>{{ day(doc.custom_relieving_date) }}</b>. You will be paid your final benefits as follows:</p>
<ol>
<li>Salary to the last day of work i.e. <b>{{ day(doc.custom_relieving_date) }}</b></li>
<li>Outstanding leave if any.</li>
<li>Less any monies owing to the company.</li>
</ol>
<p>Before any payment is made, you will be expected to;</p>
<ol type="I">
<li>Accept this letter by signing and dating a copy which will be kept on your personal file.</li>
<li>Hand in to your head of department all company property in your possession.</li>
</ol>
<p>On behalf of management, we thank you for the services you have rendered to the company and wish you all the best of luck in your future undertakings.</p>
<p>Yours faithfully,</p>
<div class="sign-off">
<p>&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</p>
<p class="who">{{ v((frappe.db.get_value("Employee", signer, "employee_name") if signer else "") | upper) }}</p>
<p class="who">EXECUTIVE DIRECTOR</p>
</div>
<p class="ack">I&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; have read and understood the terms and conditions in this letter and agree to it.</p>
<p>Sign&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; Date&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</p>
<p>Witness HRM&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; Sign&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; Date&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</p>
<p>Witness Legal Manager&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; Sign&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; Date&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</p>
{%- endif %}
</div>
